-- 0010 (APPLIED 2026-10-16): entered teams to pick from, plus the B green (4 teams, 3 games) for the Women's Vet/Novice Pairs.
-- Entered teams copied from the event's entries sheet. B green rinks are shown as 9 and 10 until the real ones are set in the app.
create table if not exists public.run_entries (id serial primary key, event_id text not null, green text check (green in ('A','B')), name text not null, unique (event_id, name));
alter table public.run_entries enable row level security;
create policy "admins run entries" on public.run_entries for all to authenticated using (public.is_link_admin()) with check (public.is_link_admin());
